Use Convex 1.44.0. The existing internal mutation writes an access log. getDocument must queue that log in a separate transaction after getDocument succeeds. The log must not be written as nested work inside the current transaction.

```ts
import { internalMutation, mutation } from "./_generated/server";
import { v } from "convex/values";
import { internal } from "./_generated/api";
export const logAccess = internalMutation({
  args: { documentId: v.id("documents"), action: v.string() },
  handler: async (ctx, args) => { await ctx.db.insert("accessLogs", args); return null; },
});
export const candidate = mutation({
  args: { documentId: v.id("documents") },
  handler: async (ctx, args) => {
    const document = await ctx.db.get("documents", args.documentId);
    if (!document) throw new Error("Document not found");
    const logArgs = { documentId: args.documentId, action: "read" };
    /* OPTION */
    return document;
  },
});
